package com.mamtrex.hospital.medication;
import com.mamtrex.hospital.shared.BaseEntity; import jakarta.persistence.*;
@Entity @Table(name="medication_orders") public class MedicationOrder extends BaseEntity { private String patientId; private String drugId; private String dose; private String route; private String frequency; protected MedicationOrder(){} public MedicationOrder(String patientId, String drugId, String dose, String route, String frequency){this.patientId=patientId; this.drugId=drugId; this.dose=dose; this.route=route; this.frequency=frequency;} public String getPatientId(){return patientId;} public String getDrugId(){return drugId;} public String getDose(){return dose;} public String getRoute(){return route;} public String getFrequency(){return frequency;} }
